apps/web/src/app/todos/todo-list.tsx:
// 이번 라운드에서 만든 파일
export function TodoList({ items }) {
	if (items.length === 0)
		return (
			<section className="py-12 text-center">
				<h2 className="text-lg font-medium">할 일이 없어요</h2>
				<p>새 할 일을 더해 보세요</p>
			</section>
		);
	return <ul>{items.map((t) => <li key={t.id}>{t.title}</li>)}</ul>;
}

